B.N2=new A.dO("traffic","Traffic light","Traffic light","Basics","Beginner","Sequence three LEDs with timing.","Three LEDs and a button","V2 \xb7 Uno \xb7 ESP32",'// Traffic light\n// Red, amber and green LEDs on pins 4, 5 and 6.\n// A push button between pin 2 and GND asks the light to change.\n#define BUTTON_PIN 2\n\nconst int RED = 4;\nconst int AMBER = 5;\nconst int GREEN = 6;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(RED, OUTPUT);\n  pinMode(AMBER, OUTPUT);\n  pinMode(GREEN, OUTPUT);\n  pinMode(BUTTON_PIN, INPUT_PULLUP);\n}\n\nvoid show(int pin, String name) {\n  digitalWrite(RED, pin == RED);\n  digitalWrite(AMBER, pin == AMBER);\n  digitalWrite(GREEN, pin == GREEN);\n  Serial.println(name);\n}\n\nvoid loop() {\n  show(GREEN, "green");\n  // Stay green for 5 seconds, or until the button is pressed\n  unsigned long start = millis();\n  while (digitalRead(BUTTON_PIN) == HIGH && millis() - start < 5000) {\n    delay(20);\n  }\n  show(AMBER, "amber");\n  delay(1000);\n  show(RED, "red");\n  delay(4000);\n}\n',null,B.UG,"TrafficLight",B.UB)
B.MY=new A.dO("ultrasonic","Ultrasonic distance","Ultrasonic distance","Sensors","Intermediate","Measure distance and print it.","Sonar readings to serial","RoboCore V2",u.X,null,null,"UltrasonicDistance",null)
B.MS=new A.dO("tones","Buzzer tones","Buzzer tones","Sound & light","Beginner","Play notes with tone() and noTone().","A rising scale","V2 \xb7 Uno \xb7 ESP32","// Buzzer tones\n// Plays a rising scale on the buzzer (pin 8).\nconst int BUZZER = 8;\n\nvoid setup() {\n  pinMode(BUZZER, OUTPUT);\n}\n\nvoid loop() {\n  tone(BUZZER, 262, 300);   // C4\n  delay(350);\n  tone(BUZZER, 330, 300);   // E4\n  delay(350);\n  tone(BUZZER, 392, 300);   // G4\n  delay(350);\n  tone(BUZZER, 523, 600);   // C5\n  delay(650);\n  noTone(BUZZER);\n  delay(1000);\n}\n",null,null,"BuzzerTones",null)
B.N1=new A.dO("motors","Motor control","Motor control","Robotics","Intermediate","Drive, reverse and turn.","Both motor ports","RoboCore V2",'// Motor control\n// Drives forward, reverses, then turns on the spot.\n#include <RoboCoreMotors.h>\n\nRoboCoreMotors motors;\n\nvoid setup() {\n  Serial.begin(115200);\n  motors.begin();\n}\n\nvoid loop() {\n  Serial.println("forward");\n  motors.drive(60, 60);\n  delay(1500);\n  Serial.println("reverse");\n  motors.drive(-60, -60);\n  delay(1500);\n  Serial.println("turn");\n  motors.drive(-50, 50);\n  delay(800);\n  motors.stop();\n  delay(1000);\n}\n',null,null,"MotorControl",null)
