B.MW=new A.dO("obstacle","Obstacle avoider","Obstacle avoider","Robotics","Advanced","Steer around walls with sonar.","Sonar + motors","RoboCore V2",'// Obstacle avoider\n// Drives forward and turns left when something is closer than 20 cm.\n#include <RoboCoreMotors.h>\n#include <RoboCoreSensors.h>\n\nRoboCoreMotors motors;\nSonar sonar;\n\nconst int LIMIT_CM = 20;\n\nvoid setup() {\n  Serial.begin(115200);\n  motors.begin();\n  sonar.begin();\n}\n\nvoid loop() {\n  float cm = sonar.distanceCm();\n  Serial.print("distance_cm=");\n  Serial.println(cm, 1);\n\n  if (cm < LIMIT_CM) {\n    Serial.println("obstacle \u2014 turning left");\n    motors.drive(-50, 50);\n    delay(400);\n  } else {\n    motors.drive(60, 60);\n  }\n  delay(250);\n}\n',null,null,"ObstacleAvoider",null)
